import operator
import re


_NUMBER_RE = re.compile(r"[+-]?[0-9]+\Z")
_PREFIX_RE = re.compile(r"\AWhat is(?:\s+|\?)")
_OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied_by": operator.mul,
    "divided_by": operator.floordiv,
}
_MULTIWORD_OPERATORS_RE = re.compile(r"\b(multiplied|divided)\s+by\b")


def _is_number(token):
    return _NUMBER_RE.fullmatch(token) is not None


def answer(question):
    """Evaluate a supported arithmetic word problem from left to right."""
    if not isinstance(question, str):
        raise ValueError("unknown operation")

    question = question.strip()
    if _PREFIX_RE.match(question) is None:
        raise ValueError("unknown operation")
    if not question.endswith("?"):
        raise ValueError("syntax error")

    expression = question[len("What is"):-1].strip()
    if not expression:
        raise ValueError("syntax error")

    expression = _MULTIWORD_OPERATORS_RE.sub(
        lambda match: f"{match.group(1)}_by", expression
    )
    tokens = expression.split()

    result = None
    pending_operation = None
    expecting_number = True

    for token in tokens:
        if expecting_number:
            if not _is_number(token):
                if token in _OPERATIONS:
                    raise ValueError("syntax error")
                raise ValueError("unknown operation")

            number = int(token)
            if pending_operation is None:
                result = number
            else:
                result = _OPERATIONS[pending_operation](result, number)
                pending_operation = None
            expecting_number = False
            continue

        if token in _OPERATIONS:
            pending_operation = token
            expecting_number = True
        elif _is_number(token):
            raise ValueError("syntax error")
        else:
            raise ValueError("unknown operation")

    if expecting_number:
        raise ValueError("syntax error")
    return result

