import re


_NUMBER_RE = re.compile(r"[+-]?[0-9]+\Z")
_PREFIX_RE = re.compile(r"\AWhat is(?:\s+|\?)")
_OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": operator.floordiv,
}
_INCOMPLETE_OPERATORS = {"multiplied", "divided"}
_TOKEN_RE = re.compile(
    r"(?<!\S)(?:multiplied\s+by|divided\s+by)(?!\S)|\S+"
)


def _is_number(token):
    return _NUMBER_RE.fullmatch(token) is not None


def answer(question):
    """Evaluate a supported arithmetic word problem from left to right."""
    if not isinstance(question, str):
        raise ValueError("unknown operation")

    question = question.strip()
    if _PREFIX_RE.match(question) is None:
        raise ValueError("unknown operation")
    if not question.endswith("?"):
        raise ValueError("syntax error")

    expression = question[len("What is"):-1].strip()
